const items = $input.all();
let competitorCount = 0;
const competitors = [];

for (const item of items) {
  if (item.json.totalItems) {
    competitorCount += item.json.totalItems;
    if (item.json.items) {
      for (const book of item.json.items) {
        competitors.push({
          title: book.volumeInfo?.title,
          publisher: book.volumeInfo?.publisher,
          publishedDate: book.volumeInfo?.publishedDate,
          source: 'Google Books'
        });
      }
    }
  }
}

return [{
  json: {
    work_id: $node['Get High Priority Works'].json.id,
    competitor_count: competitorCount,
    competitors: competitors,
    analysis_date: new Date().toISOString(),
    market_saturation: competitorCount > 100 ? 'High' : competitorCount > 50 ? 'Medium' : 'Low'
  }
}];
